/* Bytewise — CS 1337, CS 2305, CS 2336, CS 2340 */
'use strict';
const L = (h, body, viz, vizOpts) => ({ h, body, viz, vizOpts });
const idiv = (a, b) => Math.trunc(a / b), imod = (a, b) => a - b * Math.trunc(a / b);

/* ============================== CS 1337 · C++ ============================== */
CH.push({ id: 'expressions', course: '1337', ext: '.cpp', title: 'Types, operators & integer math', blurb: 'Integer division, modulus, casting and ++: where most first exam points are lost.',
  learn: [L('Integer division throws away the remainder', `<p>When both operands are <code>int</code>, <code>/</code> gives an <code>int</code>: the fraction is <b>truncated toward zero</b>, not rounded. <code>%</code> gives the remainder, and its sign follows the left operand.</p>${code('int a = 17, b = 5;\ncout << a / b;   // 3\ncout << a % b;   // 2\ncout << -17 / 5; // -3  (toward zero)\ncout << -17 % 5; // -2\ncout << 17 / 5.0;  // 3.4  (one double makes it double math)')}<p class="trap"><b>Trap:</b> <code>(double)(a / b)</code> is <b>3.0</b>, because the division already happened in int. <code>(double)a / b</code> is <b>3.4</b>.</p>`),
    L('Precedence and ++', `<p>Precedence, high to low: <code>()</code> → unary <code>++ -- !</code> → <code>* / %</code> → <code>+ -</code> → comparisons → <code>&&</code> → <code>||</code> → assignment. Operators of equal precedence go left to right.</p>${code('int x = 5;\nint y = x++ * 2;  // uses 5, THEN x becomes 6  → y = 10\nint z = ++x * 2;  // x becomes 7 FIRST       → z = 14')}<p class="note"><b>Postfix</b> <code>x++</code> hands back the old value. <b>Prefix</b> <code>++x</code> increments first and hands back the new one.</p>`, 'tracer', { prog: 'nested loops' })],
  gen() { const t = R.int(0, 3);
    if (t === 0) { const a = R.int(11, 60), b = R.int(3, 9), c = R.int(2, 6), v = idiv(a, b) * c + imod(a, b); return numQ(`What does this print?${code(`int a = ${a}, b = ${b}, c = ${c};\ncout << a / b * c + a % b;`)}`, v, '', [`a / b = ${a} / ${b} = <b>${idiv(a, b)}</b> (integer division drops the remainder)`, `× c → ${idiv(a, b) * c}`, `a % b = ${imod(a, b)}`, `${idiv(a, b) * c} + ${imod(a, b)} = <b>${v}</b>`], { tol: 0 }); }
    if (t === 1) { const b = R.int(2, 9), a = b * R.int(2, 6) + R.int(1, b - 1), r1 = idiv(a, b), r2 = a / b; return mcFrom(`What does <code>cout &lt;&lt; (double)(${a} / ${b}) &lt;&lt; " " &lt;&lt; (double)${a} / ${b};</code> print? (assume fixed notation, up to 4 decimals)`, `${+r1.toFixed(4)} ${+r2.toFixed(4)}`, [`${+r2.toFixed(4)} ${+r2.toFixed(4)}`, `${r1} ${r1}`, `${+r2.toFixed(4)} ${r1}`], [`(double)(${a} / ${b}): the int division happens first → ${r1}, then becomes ${r1}.0`, `(double)${a} / ${b}: ${a} becomes a double first, so it's real division → ${+r2.toFixed(4)}`]); }
    if (t === 2) { const x = R.int(2, 9), k = R.int(2, 4); const y = x * k, x1 = x + 1, z = (x1 + 1) * k; return mcFrom(`What are y, z and x after this runs?${code(`int x = ${x};\nint y = x++ * ${k};\nint z = ++x * ${k};`)}`, `y=${y}, z=${z}, x=${x + 2}`, [`y=${(x + 1) * k}, z=${z}, x=${x + 2}`, `y=${y}, z=${x1 * k}, x=${x + 2}`, `y=${y}, z=${z}, x=${x + 1}`], [`x++ uses ${x}, so y = ${x}×${k} = ${y}; then x = ${x1}`, `++x makes x = ${x1 + 1} first, so z = ${x1 + 1}×${k} = ${z}`, `final x = ${x + 2}`]); }
    const b = R.int(3, 7), a = -(b * R.int(2, 8) + R.int(1, b - 1)); return mcFrom(`In C++, what is <code>${a} / ${b}</code> and <code>${a} % ${b}</code>?`, `${idiv(a, b)} and ${imod(a, b)}`, [`${Math.floor(a / b)} and ${((a % b) + b) % b}`, `${idiv(a, b)} and ${-imod(a, b)}`, `${Math.floor(a / b)} and ${imod(a, b)}`], ['C++ integer division truncates toward zero.', `${a} / ${b} = ${(a / b).toFixed(2)} → <b>${idiv(a, b)}</b>`, `a % b = a − b·(a/b) = ${a} − ${b}·(${idiv(a, b)}) = <b>${imod(a, b)}</b> (same sign as a)`]); } });

CH.push({ id: 'loops', course: '1337', ext: '.cpp', title: 'Loops & tracing', blurb: 'Count iterations and track variables by hand, the way exams make you.',
  learn: [L('Count iterations before you trace', `<p>For <code>for (int i = a; i &lt; b; i += s)</code> with a positive step, the body runs <b>⌈(b − a)/s⌉</b> times (0 if a ≥ b). With <code>&lt;=</code>, it's ⌊(b − a)/s⌋ + 1.</p><p>Nested loops <b>multiply</b> when the inner bounds are fixed. If the inner loop depends on <code>i</code>, add up the inner counts instead: <code>for (j = 0; j &lt; i; j++)</code> inside <code>i = 0..n−1</code> runs 0 + 1 + … + (n−1) = n(n−1)/2 times.</p>`),
    L('Trace with a table', `<p>Make one column per variable and one row per iteration. Update in the exact order the code does. Use the tracer below and predict each line before you step.</p>`, 'tracer', { prog: 'while + modulo' })],
  gen() { const t = R.int(0, 3);
    if (t === 0) { const a = R.int(0, 5), b = R.int(12, 40), s = R.int(2, 5), le = R.pick([true, false]); let c = 0; for (let i = a; le ? i <= b : i < b; i += s) c++; return numQ(`How many times does the body run?${code(`for (int i = ${a}; i ${le ? '<=' : '<'} ${b}; i += ${s}) {\n  // body\n}`)}`, c, 'times', [`i takes the values ${a}, ${a + s}, ${a + 2 * s}, … while i ${le ? '≤' : '<'} ${b}`, le ? `⌊(${b} − ${a})/${s}⌋ + 1 = <b>${c}</b>` : `⌈(${b} − ${a})/${s}⌉ = <b>${c}</b>`], { tol: 0 }); }
    if (t === 1) { const n = R.int(4, 9), k = R.pick(['i', 'i * i', '2 * i + 1']); let sum = 0; for (let i = 1; i <= n; i++) sum += k === 'i' ? i : k === 'i * i' ? i * i : 2 * i + 1; return numQ(`What is printed?${code(`int sum = 0;\nfor (int i = 1; i <= ${n}; i++)\n  sum += ${k};\ncout << sum;`)}`, sum, '', [`add ${k} for i = 1 … ${n}`, `${[...Array(n)].map((_, i) => { i++; return k === 'i' ? i : k === 'i * i' ? i * i : 2 * i + 1; }).join(' + ')} = <b>${sum}</b>`], { tol: 0 }); }
    if (t === 2) { const n = R.int(4, 9), m = R.int(2, 5); const dep = R.pick([true, false]); let c = 0; for (let i = 0; i < n; i++) for (let j = 0; j < (dep ? i : m); j++) c++; return numQ(`How many times does <code>count++</code> run?${code(`int count = 0;\nfor (int i = 0; i < ${n}; i++)\n  for (int j = 0; j < ${dep ? 'i' : m}; j++)\n    count++;`)}`, c, '', dep ? [`the inner loop runs i times: 0 + 1 + … + ${n - 1}`, `= ${n}·${n - 1}/2 = <b>${c}</b>`] : [`independent bounds multiply`, `${n} × ${m} = <b>${c}</b>`], { tol: 0 }); }
    let n = R.int(100, 9999), s = 0, d = 0; const n0 = n; while (n > 0) { s += n % 10; n = Math.floor(n / 10); d++; } return mcFrom(`What does this print?${code(`int n = ${n0}, s = 0, d = 0;\nwhile (n > 0) {\n  s += n % 10;\n  n /= 10;\n  d++;\n}\ncout << s << " " << d;`)}`, `${s} ${d}`, [`${s} ${d + 1}`, `${s - n0 % 10} ${d}`, `${n0 % 10} ${d}`], ['n % 10 peels off the last digit; n /= 10 drops it.', `digits of ${n0}: ${[...String(n0)].join(' + ')} = ${s}`, `${d} iterations (one per digit) → <b>${s} ${d}</b>`]); } });

CH.push({ id: 'functions', course: '1337', ext: '.cpp', title: 'Functions & pass by reference', blurb: 'By value copies. By reference aliases. Know which one changes the caller.',
  learn: [L('Value vs reference', `<p><b>Pass by value</b> (<code>int x</code>) gives the function a copy: changes vanish when it returns. <b>Pass by reference</b> (<code>int&amp; x</code>) makes the parameter another name for the caller's variable, so changes stick.</p>${code('void a(int x)  { x = x * 2; }\nvoid b(int& x) { x = x * 2; }\n\nint n = 5;\na(n);  // n is still 5\nb(n);  // n is now 10')}<p class="note">Arrays are always passed as a pointer to the first element, so a function <i>can</i> change array contents. Use <code>const int arr[]</code> to forbid it.</p>`),
    L('Default arguments, overloading and scope', `<p>Overloads must differ in parameter <b>types or count</b>, not just the return type. A local variable with the same name as a global <b>shadows</b> it inside that block. Static locals keep their value between calls.</p>${code('int counter() {\n  static int c = 0;  // initialized once\n  return ++c;\n}\n// counter(), counter(), counter() → 1, 2, 3')}`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const n = R.int(2, 9), m = R.int(2, 9), d = R.int(2, 5); const ref1 = R.pick([true, false]), ref2 = R.pick([true, false]); const A = ref1 ? n + d : n, B = ref2 ? m * d : m;
      return mcFrom(`What prints?${code(`void f(int${ref1 ? '&' : ''} x, int${ref2 ? '&' : ''} y) {\n  x = x + ${d};\n  y = y * ${d};\n}\nint main() {\n  int a = ${n}, b = ${m};\n  f(a, b);\n  cout << a << " " << b;\n}`)}`, `${A} ${B}`, [`${n + d} ${m * d}`, `${n} ${m}`, `${ref1 ? n : n + d} ${ref2 ? m : m * d}`], [`x is passed by ${ref1 ? 'reference → a changes' : 'value → a is unchanged'}`, `y is passed by ${ref2 ? 'reference → b changes' : 'value → b is unchanged'}`, `→ <b>${A} ${B}</b>`]); }
    if (t === 1) { const k = R.int(3, 6); return numQ(`What is the last number printed?${code(`int tick() {\n  static int c = 10;\n  c += 2;\n  return c;\n}\nint main() {\n  for (int i = 0; i < ${k}; i++) cout << tick() << " ";\n}`)}`, 10 + 2 * k, '', ['a static local is initialized once and keeps its value between calls', `each call adds 2: ${[...Array(k)].map((_, i) => 12 + 2 * i).join(', ')}`, `last = <b>${10 + 2 * k}</b>`], { tol: 0 }); }
    return mcFrom('Which pair of declarations is <b>not</b> a legal overload?', 'int f(int);  double f(int);', ['int f(int);  int f(double);', 'int f(int);  int f(int, int);', 'void f(char);  void f(string);'], ['Overloads must differ in parameter list (types or count).', 'Changing only the return type is ambiguous at the call site: <b>int f(int); double f(int);</b>']); } });

CH.push({ id: 'pointers', course: '1337', ext: '.cpp', title: 'Arrays & pointers', blurb: 'Addresses, dereferencing and pointer arithmetic, without the segfaults.',
  learn: [L('A pointer holds an address', `<p><code>&amp;x</code> is the address of x. <code>int* p = &amp;x;</code> stores it. <code>*p</code> follows the pointer to the value. Changing <code>*p</code> changes x.</p>${code('int x = 5;\nint* p = &x;\n*p = 9;      // x is now 9\nint arr[4] = {2, 4, 6, 8};\nint* q = arr;     // same as &arr[0]\ncout << *(q + 2); // 6  — moves 2 ints, not 2 bytes\ncout << q[3];     // 8  — q[i] means *(q + i)')}`, 'tracer', { prog: 'pointers (C++)' }),
    L('Dynamic memory', `<p><code>new</code> allocates on the heap and returns a pointer. Every <code>new</code> needs a matching <code>delete</code> (and <code>new[]</code> needs <code>delete[]</code>), or you leak memory.</p>${code('int* a = new int[n];\n// ... use a[0..n-1]\ndelete[] a;\na = nullptr;  // avoid a dangling pointer')}<p class="trap"><b>Classic bugs:</b> returning a pointer to a local variable, using memory after <code>delete</code>, and off-by-one indexing (valid indices are 0 to n−1).</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const a = [...Array(6)].map(() => R.int(1, 30)), i = R.int(0, 2), j = R.int(1, 3); const v = a[i + j]; return numQ(`What prints?${code(`int a[6] = {${a.join(', ')}};\nint* p = a + ${i};\ncout << *(p + ${j});`)}`, v, '', [`p points to a[${i}]`, `p + ${j} points to a[${i + j}]`, `*(p + ${j}) = a[${i + j}] = <b>${v}</b>`], { tol: 0 }); }
    if (t === 1) { const x = R.int(2, 9), y = R.int(2, 9), d = R.int(1, 5); return mcFrom(`What prints?${code(`int x = ${x}, y = ${y};\nint* p = &x;\nint* q = &y;\n*p = *q + ${d};\np = q;\n*p = *p * 2;\ncout << x << " " << y;`)}`, `${y + d} ${y * 2}`, [`${y + d} ${(y + d) * 2}`, `${(y + d) * 2} ${y}`, `${x} ${y * 2}`], [`*p = *q + ${d} → x = ${y} + ${d} = ${y + d}`, 'p = q → now p points to y', `*p = *p * 2 → y = ${y * 2}`, `→ <b>${y + d} ${y * 2}</b>`]); }
    return mcFrom('Which code has a <b>dangling pointer</b>?', 'int* f() { int x = 5; return &x; }', ['int* f() { int* x = new int(5); return x; }', 'int* f(int* x) { return x; }', 'void f(int& x) { x = 5; }'], ['A local variable is destroyed when the function returns.', 'Returning <b>&x</b> of a local gives an address that is no longer valid.']); } });

CH.push({ id: 'recursion', course: '1337', ext: '.cpp', title: 'Recursion', blurb: 'Base case, recursive case, and how to trace the call stack.',
  learn: [L('Two parts, every time', `<p>A recursive function needs a <b>base case</b> that answers without recursing, and a <b>recursive case</b> that moves toward it. Each call gets its own copy of the parameters on the call stack.</p>${code('int sumTo(int n) {\n  if (n == 0) return 0;      // base case\n  return n + sumTo(n - 1);   // smaller problem\n}')}<p>To trace, expand calls going down, then combine return values coming back up.</p>`, 'tracer', { prog: 'recursion (factorial)' }),
    L('Count the calls', `<p>A function that calls itself <b>once</b> per level makes about n calls. One that calls itself <b>twice</b> (like naive Fibonacci) makes about 2ⁿ. That's why memoization matters.</p>`, 'rectree')],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const n = R.int(3, 6), b = R.int(2, 3); const f = k => k <= 0 ? 1 : b * f(k - 1) + k; return numQ(`What does <code>f(${n})</code> return?${code(`int f(int n) {\n  if (n <= 0) return 1;\n  return ${b} * f(n - 1) + n;\n}`)}`, f(n), '', [...[...Array(n + 1)].map((_, k) => `f(${k}) = ${k === 0 ? 1 : `${b}·f(${k - 1}) + ${k} = ${b}·${f(k - 1)} + ${k} = ${f(k)}`}`), `→ <b>${f(n)}</b>`], { tol: 0 }); }
    if (t === 1) { const n = R.int(3, 7); const calls = k => k < 2 ? 1 : 1 + calls(k - 1) + calls(k - 2); return numQ(`How many total calls (including the first) does <code>fib(${n})</code> make?${code('int fib(int n) {\n  if (n < 2) return n;\n  return fib(n - 1) + fib(n - 2);\n}')}`, calls(n), 'calls', ['C(n) = 1 + C(n−1) + C(n−2), with C(0) = C(1) = 1', ...[...Array(n - 1)].map((_, i) => `C(${i + 2}) = ${calls(i + 2)}`), `→ <b>${calls(n)}</b>`], { tol: 0 }); }
    const s = R.pick(['abcde', 'stack', 'recur', 'loops']); return mcFrom(`What prints?${code(`void p(string s, int i) {\n  if (i == s.size()) return;\n  p(s, i + 1);\n  cout << s[i];\n}\np("${s}", 0);`)}`, [...s].reverse().join(''), [s, s.slice(1) + s[0], [...s].reverse().join('').slice(1)], ['The print happens <b>after</b> the recursive call returns.', 'The deepest call (last character) prints first.', `→ <b>${[...s].reverse().join('')}</b>`]); } });

/* ============================== CS 2305 · Discrete Math I ============================== */
const TF = b => b ? 'T' : 'F';
const PROPS = [['p → q', (p, q) => !p || q], ['p ∧ ¬q', (p, q) => p && !q], ['¬p ∨ q', (p, q) => !p || q], ['p ↔ q', (p, q) => p === q], ['p ⊕ q', (p, q) => p !== q], ['¬(p ∧ q)', (p, q) => !(p && q)], ['(p → q) ∧ (q → p)', (p, q) => (!p || q) && (!q || p)], ['¬p → ¬q', (p, q) => p || !q]];
CH.push({ id: 'logic', course: '2305', ext: '.md', title: 'Propositional logic', blurb: 'Truth tables, implications, equivalences and the contrapositive.',
  learn: [L('Five connectives', `<table class="t"><tr><th>p</th><th>q</th><th>¬p</th><th>p ∧ q</th><th>p ∨ q</th><th>p → q</th><th>p ↔ q</th></tr>${[[1, 1], [1, 0], [0, 1], [0, 0]].map(([p, q]) => `<tr><td>${TF(p)}</td><td>${TF(q)}</td><td>${TF(!p)}</td><td>${TF(p && q)}</td><td>${TF(p || q)}</td><td>${TF(!p || q)}</td><td>${TF(p === q)}</td></tr>`).join('')}</table><p><b>p → q is false only when p is true and q is false.</b> A false hypothesis makes the implication "vacuously" true.</p>`),
    L('Converse, inverse, contrapositive', `<p>For p → q: the <b>converse</b> is q → p, the <b>inverse</b> is ¬p → ¬q, and the <b>contrapositive</b> is ¬q → ¬p. Only the contrapositive is equivalent to the original. (The converse and inverse are equivalent to each other.)</p><p>Key laws: De Morgan ¬(p ∧ q) ≡ ¬p ∨ ¬q; p → q ≡ ¬p ∨ q; ¬(p → q) ≡ p ∧ ¬q.</p>`, 'kmap')],
  gen() { const t = R.int(0, 3);
    if (t === 0) { const [s, f] = R.pick(PROPS), p = R.pick([true, false]), q = R.pick([true, false]); return mcFrom(`If p is <b>${TF(p)}</b> and q is <b>${TF(q)}</b>, what is the truth value of <b>${s}</b>?`, TF(f(p, q)), ['T', 'F'], [`substitute p = ${TF(p)}, q = ${TF(q)}`, `${s} → <b>${TF(f(p, q))}</b>`]); }
    if (t === 1) { const [s, f] = R.pick(PROPS); const n = [[1, 1], [1, 0], [0, 1], [0, 0]].filter(([p, q]) => f(!!p, !!q)).length; return numQ(`In how many of the 4 rows of its truth table is <b>${s}</b> true?`, n, 'rows', [[[1, 1], [1, 0], [0, 1], [0, 0]].map(([p, q]) => `p=${TF(p)}, q=${TF(q)}: ${TF(f(!!p, !!q))}`).join(' · '), `→ <b>${n}</b>`], { tol: 0 }); }
    if (t === 2) { const [a, b] = R.pick([['it rains', 'the game is canceled'], ['n is even', 'n² is even'], ['you study', 'you get an A'], ['the code compiles', 'the program runs']]), kind = R.pick(['contrapositive', 'converse', 'inverse']); const ans = { contrapositive: `If ${b.replace(/is /, 'is not ').replace(/you (\w+)/, "you don't $1").replace(/the code compiles/, "the code doesn't compile")}`, converse: '', inverse: '' };
      const neg = s => s.includes(' is ') ? s.replace(' is ', ' is not ') : s.startsWith('you ') ? s.replace(/^you (\w+)/, "you don't $1").replace(/don't (\w+)s\b/, "don't $1") : s.replace(/^(the \w+) (\w+)s$/, "$1 doesn't $2").replace(/^it rains$/, "it doesn't rain");
      const C = { contrapositive: `If ${neg(b)}, then ${neg(a)}.`, converse: `If ${b}, then ${a}.`, inverse: `If ${neg(a)}, then ${neg(b)}.` }; return mcFrom(`What is the <b>${kind}</b> of "If ${a}, then ${b}"?`, C[kind], [...Object.values(C), `If ${a}, then ${neg(b)}.`], [`${kind}: ${kind === 'contrapositive' ? '¬q → ¬p (swap AND negate)' : kind === 'converse' ? 'q → p (swap)' : '¬p → ¬q (negate)'}`, `→ <b>${C[kind]}</b>`, kind === 'contrapositive' ? 'It is the only one logically equivalent to the original.' : 'This one is NOT equivalent to the original.']); }
    const Q = R.pick([['∀x P(x)', '∃x ¬P(x)', ['∀x ¬P(x)', '∃x P(x)', '¬∃x P(x)']], ['∃x P(x)', '∀x ¬P(x)', ['∃x ¬P(x)', '∀x P(x)', '¬∀x P(x)']], ['∀x (P(x) → Q(x))', '∃x (P(x) ∧ ¬Q(x))', ['∀x (P(x) ∧ ¬Q(x))', '∃x (¬P(x) → ¬Q(x))', '∃x (P(x) → ¬Q(x))']], ['∃x ∀y P(x,y)', '∀x ∃y ¬P(x,y)', ['∃x ∃y ¬P(x,y)', '∀x ∀y ¬P(x,y)', '∃y ∀x ¬P(x,y)']]]);
    return mcFrom(`What is the negation of <b>${Q[0]}</b>?`, Q[1], Q[2], ['Push ¬ inward: flip each ∀ ↔ ∃, then negate what\'s inside.', '¬(P → Q) ≡ P ∧ ¬Q', `→ <b>${Q[1]}</b>`]); } });

const nCr = (n, r) => { if (r < 0 || r > n) return 0; let c = 1; for (let i = 0; i < r; i++) c = c * (n - i) / (i + 1); return Math.round(c); }, nPr = (n, r) => { let c = 1; for (let i = 0; i < r; i++) c *= n - i; return c; };
CH.push({ id: 'counting', course: '2305', ext: '.md', title: 'Sets & counting', blurb: 'Inclusion–exclusion, permutations, combinations and the pigeonhole principle.',
  learn: [L('Does order matter?', `<p><b>Permutations</b> (order matters): P(n, r) = n!/(n−r)!. <b>Combinations</b> (order doesn't): C(n, r) = n!/(r!(n−r)!). With repetition allowed, there are nʳ ordered choices and C(n+r−1, r) unordered ones ("stars and bars").</p><p><b>Product rule</b> for "and" (sequential choices), <b>sum rule</b> for "or" (disjoint cases).</p>`),
    L('Inclusion–exclusion & pigeonhole', `<p>|A ∪ B| = |A| + |B| − |A ∩ B|, and |A ∪ B ∪ C| = |A|+|B|+|C| − |A∩B| − |A∩C| − |B∩C| + |A∩B∩C|.</p><p><b>Pigeonhole:</b> putting N objects in k boxes forces some box to hold at least ⌈N/k⌉.</p>`)],
  gen() { const t = R.int(0, 4);
    if (t === 0) { const n = R.int(6, 12), r = R.int(2, 4); return numQ(`A club of ${n} people elects a president, vice president and ${r === 2 ? '' : 'other officers for '}${r} distinct positions. How many ways?`, nPr(n, r), 'ways', ['Distinct positions → order matters.', `P(${n}, ${r}) = ${[...Array(r)].map((_, i) => n - i).join(' × ')} = <b>${nPr(n, r)}</b>`], { tol: 0 }); }
    if (t === 1) { const n = R.int(7, 15), r = R.int(2, 5); return numQ(`How many ways can you choose a committee of ${r} from ${n} people?`, nCr(n, r), 'ways', ['A committee has no order → combination.', `C(${n}, ${r}) = ${n}! / (${r}! · ${n - r}!) = <b>${nCr(n, r)}</b>`], { tol: 0 }); }
    if (t === 2) { const N = R.int(60, 200), a = R.int(20, 60), b = R.int(20, 60), ab = R.int(5, Math.min(a, b) - 2); return numQ(`Of ${N} students, ${a} take Java, ${b} take Python and ${ab} take both. How many take <b>neither</b>?`, N - (a + b - ab), 'students', [`|J ∪ P| = ${a} + ${b} − ${ab} = ${a + b - ab}`, `neither = ${N} − ${a + b - ab} = <b>${N - (a + b - ab)}</b>`], { tol: 0 }); }
    if (t === 3) { const k = R.pick([7, 12, 26, 30]), name = { 7: 'days of the week', 12: 'months', 26: 'letters of the alphabet', 30: 'days in a 30-day month' }[k], m = R.int(2, 4); return numQ(`What is the minimum number of people needed to guarantee that at least ${m} share the same ${name.replace(/s of.*|s in.*|s$/, '')} (out of ${k} ${name})?`, k * (m - 1) + 1, 'people', [`Generalized pigeonhole: N people in ${k} boxes forces ⌈N/${k}⌉ ≥ ${m}`, `smallest N = ${k}(${m} − 1) + 1 = <b>${k * (m - 1) + 1}</b>`], { tol: 0 }); }
    const n = R.int(5, 9), r = R.int(3, 6); return numQ(`How many solutions does x₁ + x₂ + … + x${'₀₁₂₃₄₅₆₇₈₉'[r]} = ${n} have in non-negative integers?`, nCr(n + r - 1, r - 1), 'solutions', [`Stars and bars: ${n} stars, ${r - 1} bars`, `C(${n} + ${r} − 1, ${r} − 1) = C(${n + r - 1}, ${r - 1}) = <b>${nCr(n + r - 1, r - 1)}</b>`], { tol: 0 }); } });

const gcd = (a, b) => b ? gcd(b, a % b) : Math.abs(a); const modinv = (a, m) => { for (let x = 1; x < m; x++) if ((a * x) % m === 1) return x; return null; };
CH.push({ id: 'number_theory', course: '2305', ext: '.md', title: 'Number theory & modular arithmetic', blurb: 'mod, the Euclidean algorithm and modular inverses: the math behind hashing and RSA.',
  learn: [L('Euclid\'s algorithm', `<p>gcd(a, b) = gcd(b, a mod b), stopping when the second number is 0. It takes O(log min(a, b)) steps.</p>${code('gcd(252, 105) = gcd(105, 42)\n             = gcd(42, 21)\n             = gcd(21, 0) = 21')}<p>a ≡ b (mod m) means m divides a − b. You can add, subtract and multiply both sides of a congruence.</p>`),
    L('Modular inverses', `<p>The inverse of a mod m is the x with a·x ≡ 1 (mod m). It exists <b>only if gcd(a, m) = 1</b>. Find it with the extended Euclidean algorithm, or by trying x = 1, 2, … for small m.</p><p>Fast exponentiation: square-and-multiply makes aⁿ mod m O(log n).</p>`)],
  gen() { const t = R.int(0, 3);
    if (t === 0) { const g = R.int(2, 15), a = g * R.int(5, 30), b = g * R.int(3, 20); const steps = []; let x = a, y = b; while (y) { steps.push(`gcd(${x}, ${y})`); [x, y] = [y, x % y]; } return numQ(`Find gcd(${a}, ${b}).`, gcd(a, b), '', [steps.join(' = ') + ` = gcd(${x}, 0)`, `→ <b>${gcd(a, b)}</b>`], { tol: 0 }); }
    if (t === 1) { const m = R.pick([7, 11, 13, 17, 26]); let a; do a = R.int(2, m - 1); while (gcd(a, m) !== 1); const x = modinv(a, m); return numQ(`Find the inverse of ${a} modulo ${m} (a number from 0 to ${m - 1}).`, x, '', [`gcd(${a}, ${m}) = 1, so an inverse exists`, `${a} × ${x} = ${a * x} = ${Math.floor(a * x / m)}·${m} + 1`, `→ <b>${x}</b>`], { tol: 0 }); }
    if (t === 2) { const a = R.int(-50, 99), m = R.int(5, 13); const r = ((a % m) + m) % m; return numQ(`In discrete math (result between 0 and m−1), what is ${a} mod ${m}?`, r, '', [`write ${a} = ${m}q + r with 0 ≤ r < ${m}`, `${a} = ${m}·(${Math.floor(a / m)}) + ${r}`, `→ <b>${r}</b>`, a < 0 ? 'Note: C++/Java % would give a negative answer here.' : ''].filter(Boolean), { tol: 0 }); }
    const b = R.int(2, 7), e = R.int(5, 30), m = R.pick([7, 11, 13, 19]); let r = 1; for (let i = 0; i < e; i++) r = r * b % m; return numQ(`Compute ${b}<sup>${e}</sup> mod ${m}.`, r, '', [`reduce as you go (or use Fermat: ${b}<sup>${m - 1}</sup> ≡ 1 mod ${m})`, `${e} mod ${m - 1} = ${e % (m - 1)}, so ${b}<sup>${e}</sup> ≡ ${b}<sup>${e % (m - 1)}</sup> (mod ${m})`, `→ <b>${r}</b>`], { tol: 0 }); } });

CH.push({ id: 'relations', course: '2305', ext: '.md', title: 'Relations & functions', blurb: 'Reflexive, symmetric, transitive, and one-to-one vs onto.',
  learn: [L('Properties of a relation on A', `<ul><li><b>Reflexive:</b> (a, a) ∈ R for every a ∈ A.</li><li><b>Symmetric:</b> (a, b) ∈ R ⇒ (b, a) ∈ R.</li><li><b>Antisymmetric:</b> (a, b) and (b, a) both in R ⇒ a = b.</li><li><b>Transitive:</b> (a, b) and (b, c) in R ⇒ (a, c) ∈ R.</li></ul><p>An <b>equivalence relation</b> is reflexive, symmetric and transitive. A <b>partial order</b> is reflexive, antisymmetric and transitive.</p>`),
    L('Functions', `<p><b>One-to-one (injective):</b> different inputs give different outputs. <b>Onto (surjective):</b> every element of the codomain gets hit. <b>Bijective:</b> both, so it has an inverse. From an n-set to an m-set there are mⁿ functions, and P(m, n) = m!/(m−n)! one-to-one functions when m ≥ n.</p>`)],
  gen() { const t = R.int(0, 1);
    if (t === 0) { const A = [1, 2, 3]; let Rl; do Rl = A.flatMap(a => A.map(b => [a, b])).filter(() => Math.random() < .45); while (!Rl.length);
      const has = (a, b) => Rl.some(p => p[0] === a && p[1] === b), refl = A.every(a => has(a, a)), sym = Rl.every(([a, b]) => has(b, a)), anti = Rl.every(([a, b]) => a === b || !has(b, a)), tr = Rl.every(([a, b]) => Rl.every(([c, d]) => c !== b || has(a, d)));
      const props = [refl && 'reflexive', sym && 'symmetric', anti && 'antisymmetric', tr && 'transitive'].filter(Boolean).join(', ') || 'none of these';
      return textQ(`R = {${Rl.map(p => `(${p})`).join(', ')}} on A = {1, 2, 3}. Which properties does R have? (type them separated by commas, or "none")`, props, [`reflexive needs (1,1), (2,2), (3,3): ${refl ? 'yes' : 'no'}`, `symmetric: every (a,b) has (b,a): ${sym ? 'yes' : 'no'}`, `antisymmetric: no pair both ways with a ≠ b: ${anti ? 'yes' : 'no'}`, `transitive: (a,b),(b,c) ⇒ (a,c): ${tr ? 'yes' : 'no'}`, `→ <b>${props}</b>`], { check: v => { const g = v.toLowerCase(); const want = props === 'none of these' ? [] : props.split(', '); const got = ['reflexive', 'symmetric', 'antisymmetric', 'transitive'].filter(p => p === 'symmetric' ? /(^|[^i])symmetric/.test(g) : g.includes(p)); return want.length ? want.length === got.length && want.every(w => got.includes(w)) : /none/.test(g) && !got.length; } }); }
    const n = R.int(2, 4), m = R.int(n, 5); return numQ(`How many <b>one-to-one</b> functions are there from a ${n}-element set to a ${m}-element set?`, nPr(m, n), '', ['Each input must get a different output.', `${m} choices, then ${m - 1}, … : P(${m}, ${n}) = <b>${nPr(m, n)}</b>`], { tol: 0 }); } });

CH.push({ id: 'induction', course: '2305', ext: '.md', title: 'Sums, sequences & induction', blurb: 'Closed forms you need to know, and how a proof by induction is built.',
  learn: [L('Sums to memorize', `<ul><li>1 + 2 + … + n = n(n+1)/2</li><li>1² + 2² + … + n² = n(n+1)(2n+1)/6</li><li>1 + r + r² + … + rⁿ = (rⁿ⁺¹ − 1)/(r − 1)</li><li>arithmetic: (number of terms)·(first + last)/2</li></ul>`),
    L('Induction in three moves', `<p><b>1. Base case:</b> show P(1) (or P(n₀)). <b>2. Inductive hypothesis:</b> assume P(k). <b>3. Inductive step:</b> use it to prove P(k + 1). Strong induction lets you assume P(n₀) … P(k).</p><p class="note">The step for Σi = n(n+1)/2: assume 1+…+k = k(k+1)/2. Then 1+…+k+(k+1) = k(k+1)/2 + (k+1) = (k+1)(k+2)/2. ✓</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const a = R.int(1, 9), d = R.int(2, 7), n = R.int(10, 40), last = a + (n - 1) * d; return numQ(`Find ${a} + ${a + d} + ${a + 2 * d} + … + ${last}.`, n * (a + last) / 2, '', [`${n} terms (common difference ${d})`, `sum = n(first + last)/2 = ${n}(${a} + ${last})/2 = <b>${n * (a + last) / 2}</b>`], { tol: 0 }); }
    if (t === 1) { const r = R.int(2, 3), n = R.int(4, 9); return numQ(`Find Σ<sub>i=0</sub><sup>${n}</sup> ${r}<sup>i</sup>.`, (r ** (n + 1) - 1) / (r - 1), '', [`geometric series with ratio ${r}`, `(${r}<sup>${n + 1}</sup> − 1)/(${r} − 1) = <b>${(r ** (n + 1) - 1) / (r - 1)}</b>`], { tol: 0 }); }
    return mcFrom('In a proof by induction of P(n) for all n ≥ 1, what do you assume in the inductive step?', 'P(k) is true for some arbitrary k ≥ 1', ['P(k + 1) is true', 'P(n) is true for all n', 'P(1) is false'], ['You assume the hypothesis P(k)…', '…and use it to prove P(k + 1). Assuming P(k+1) would be circular.']); } });

/* ============================== CS 2336 · Java ============================== */
CH.push({ id: 'oop', course: '2336', title: 'Classes, inheritance & polymorphism', blurb: 'Which method actually runs? Overriding, overloading, super and dynamic dispatch.',
  learn: [L('Dynamic dispatch', `<p>For an <b>overridden instance method</b>, Java looks at the <b>runtime type of the object</b>, not the declared type of the variable. Fields and static methods are resolved by the <b>declared type</b>.</p>${code('class Animal { String sound() { return "..."; } }\nclass Dog extends Animal { String sound() { return "woof"; } }\n\nAnimal a = new Dog();\na.sound();  // "woof": runtime type is Dog')}<p>The compiler only lets you call methods the <b>declared</b> type has. <code>a.fetch()</code> won't compile even if Dog has it; cast first: <code>((Dog) a).fetch()</code>.</p>`),
    L('Constructors and super', `<p>A subclass constructor <b>always calls a superclass constructor first</b>, implicitly <code>super()</code> if you don't write one. So constructors run top-down: Object → Animal → Dog.</p><p><b>Overloading</b> = same name, different parameters (chosen at compile time). <b>Overriding</b> = same signature in a subclass (chosen at run time).</p><p><code>abstract</code> classes can't be instantiated; <code>interface</code>s define a contract (a class can implement many but extend only one class).</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const [A, B] = R.pick([['Shape', 'Circle'], ['Animal', 'Cat'], ['Vehicle', 'Truck'], ['Account', 'Savings']]), decl = R.pick([A, B]); const ov = R.pick([true, false]), out = decl === A && !ov ? `${A}.describe` : decl === B ? `${B}.describe` : `${B}.describe`;
      const outs = `${ov ? B : A}.describe`; return mcFrom(`What prints?${code(`class ${A} {\n  void describe() { System.out.println("${A}.describe"); }\n}\nclass ${B} extends ${A} {\n  ${ov ? `void describe() { System.out.println("${B}.describe"); }` : `void extra() { System.out.println("${B}.extra"); }`}\n}\n${decl} x = new ${B}();\nx.describe();`)}`, outs, [`${A}.describe`, `${B}.describe`, 'compile error', `${B}.extra`], [ov ? `${B} overrides describe()` : `${B} does not override describe(), so it inherits ${A}'s`, 'instance methods use the runtime type (dynamic dispatch)', `→ <b>${outs}</b>`]); void out; }
    if (t === 1) { return mcFrom(`What prints?${code('class A {\n  A() { System.out.print("A"); }\n}\nclass B extends A {\n  B() { System.out.print("B"); }\n}\nclass C extends B {\n  C() { super(); System.out.print("C"); }\n}\nnew C();')}`, 'ABC', ['C', 'CBA', 'BC'], ['Every constructor calls its superclass constructor first.', 'C() → B() → A(): A prints, then B, then C', '→ <b>ABC</b>']); }
    return mcFrom(`<code>Animal a = new Dog();</code> Dog defines <code>fetch()</code>, Animal doesn't. What happens with <code>a.fetch();</code>?`, 'Compile error', ['Calls Dog.fetch()', 'Runtime ClassCastException', 'Calls Animal.fetch() which does nothing'], ['The compiler checks method calls against the declared type (Animal).', 'Animal has no fetch() → <b>compile error</b>. Cast: ((Dog) a).fetch().']); } });

CH.push({ id: 'strings', course: '2336', title: 'Strings, == and equals', blurb: 'Reference equality vs value equality, immutability and string methods.',
  learn: [L('== compares references', `<p>For objects, <code>==</code> asks "same object in memory?". <code>.equals()</code> asks "same contents?". String literals are <b>interned</b> (shared), so two identical literals are <code>==</code>; a <code>new String(...)</code> or a string built at runtime is a different object.</p>${code('String a = "hi";\nString b = "hi";\nString c = new String("hi");\na == b        // true  (same pooled literal)\na == c        // false (different object)\na.equals(c)   // true')}`),
    L('Strings are immutable', `<p>Methods like <code>toUpperCase()</code>, <code>replace()</code> and <code>substring()</code> return a <b>new</b> String; the original never changes. <code>substring(a, b)</code> includes index a and excludes b. In loops, use <code>StringBuilder</code> to avoid making O(n²) copies.</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const s = R.pick(['computer', 'bytewise', 'recursion', 'polymorph', 'algorithm']), a = R.int(1, 3), b = R.int(a + 2, s.length - 1); return textQ(`What does <code>"${s}".substring(${a}, ${b})</code> return?`, s.slice(a, b), [`characters from index ${a} up to (not including) ${b}`, `${[...s].map((c, i) => i >= a && i < b ? `<b>${c}</b>` : c).join('')}`, `→ <b>${s.slice(a, b)}</b>`], { check: v => v.trim().replace(/^"|"$/g, '') === s.slice(a, b) }); }
    if (t === 1) { const r = [['a == b', 'true'], ['a == c', 'false'], ['a.equals(c)', 'true'], ['c == c.intern()', 'false'], ['a == c.intern()', 'true']], [ex, ans] = R.pick(r); return mcFrom(`${code('String a = "java";\nString b = "java";\nString c = new String("java");')}What is <code>${ex}</code>?`, ans, ['true', 'false', 'compile error'], ['== compares references; equals compares contents', 'literals are pooled; new String makes a separate object; intern() returns the pooled one', `→ <b>${ans}</b>`]); }
    return mcFrom(`What prints?${code('String s = "data";\ns.toUpperCase();\ns.concat("!");\nSystem.out.println(s);')}`, 'data', ['DATA!', 'DATA', 'data!'], ['Strings are immutable: toUpperCase() and concat() return new strings.', 'The results were thrown away, so s is still <b>data</b>.']); } });

CH.push({ id: 'exceptions', course: '2336', title: 'Exceptions', blurb: 'try / catch / finally order, checked vs unchecked, and what runs when.',
  learn: [L('The flow', `<p>When an exception is thrown, Java skips the rest of the <code>try</code> block, runs the <b>first</b> matching <code>catch</code> (subclass catches must come before superclass ones), then <b>always</b> runs <code>finally</code>, even if there was a <code>return</code>.</p>${code('try {\n  System.out.print("1");\n  int x = 5 / 0;            // ArithmeticException\n  System.out.print("2");    // skipped\n} catch (ArithmeticException e) {\n  System.out.print("3");\n} finally {\n  System.out.print("4");\n}\nSystem.out.print("5");      // prints 1345')}`),
    L('Checked vs unchecked', `<p><b>Checked</b> exceptions (IOException, FileNotFoundException) must be caught or declared with <code>throws</code>. <b>Unchecked</b> exceptions are subclasses of <code>RuntimeException</code> (NullPointerException, ArrayIndexOutOfBoundsException, ArithmeticException) and don't have to be.</p>`)],
  gen() { const t = R.int(0, 1);
    if (t === 0) { const thr = R.pick(['none', 'arith', 'index']), catchArith = R.pick([true, false]); const out = thr === 'none' ? '1245' : '1345';
      const line = thr === 'none' ? 'int x = 6 / 2;' : thr === 'arith' ? 'int x = 6 / 0;' : 'int[] a = new int[2]; a[2] = 1;';
      return mcFrom(`What prints (ignore any stack trace)?${code(`try {\n  System.out.print("1");\n  ${line}\n  System.out.print("2");\n} catch (${catchArith ? 'ArithmeticException' : 'ArrayIndexOutOfBoundsException'} e) {\n  System.out.print("3");\n} catch (RuntimeException e) {\n  System.out.print("3");\n} finally {\n  System.out.print("4");\n}\nSystem.out.print("5");`)}`, out, ['1245', '12345', '1345', '145', '134', '1235'], [thr === 'none' ? 'nothing is thrown, so no catch runs' : `${thr === 'arith' ? 'ArithmeticException' : 'ArrayIndexOutOfBoundsException'} is thrown; "2" is skipped`, thr === 'none' ? '' : 'a catch block matches (both are RuntimeExceptions), so "3" prints', 'finally always runs → "4"', 'the exception was handled, so execution continues → "5"', `→ <b>${out}</b>`].filter(Boolean)); }
    const e = R.pick([['IOException', 'checked'], ['FileNotFoundException', 'checked'], ['NullPointerException', 'unchecked'], ['ArithmeticException', 'unchecked'], ['ClassCastException', 'unchecked'], ['InterruptedException', 'checked'], ['IllegalArgumentException', 'unchecked']]); return mcFrom(`Is <b>${e[0]}</b> checked or unchecked?`, e[1], ['checked', 'unchecked'], ['Unchecked = subclasses of RuntimeException (or Error).', `${e[0]} is <b>${e[1]}</b>${e[1] === 'checked' ? ': you must catch it or declare throws' : ''}.`]); } });

CH.push({ id: 'collections', course: '2336', title: 'Generics & collections', blurb: 'ArrayList, LinkedList, HashMap and the Big-O of their operations.',
  learn: [L('Pick the right structure', `<table class="t"><tr><th>operation</th><th>ArrayList</th><th>LinkedList</th><th>HashMap</th><th>TreeMap</th></tr><tr><td>get(i)</td><td>O(1)</td><td>O(n)</td><td>—</td><td>—</td></tr><tr><td>add at end</td><td>O(1)*</td><td>O(1)</td><td>—</td><td>—</td></tr><tr><td>add/remove at front</td><td>O(n)</td><td>O(1)</td><td>—</td><td>—</td></tr><tr><td>contains/search</td><td>O(n)</td><td>O(n)</td><td>O(1) avg</td><td>O(log n)</td></tr><tr><td>put/get by key</td><td>—</td><td>—</td><td>O(1) avg</td><td>O(log n)</td></tr></table><p>* amortized: the backing array doubles when full.</p>`, 'lists'),
    L('ArrayList gotchas', `${code('ArrayList<Integer> list = new ArrayList<>(List.of(5, 3, 8));\nlist.add(1, 9);        // [5, 9, 3, 8]  insert at index 1\nlist.remove(0);        // [9, 3, 8]     remove(int index)\nlist.remove(Integer.valueOf(8)); // [9, 3] remove(Object)\nlist.set(0, 7);        // [7, 3]')}<p class="trap"><code>remove(int)</code> removes by <b>index</b>; to remove a value from an Integer list, box it. Generics only take reference types: <code>ArrayList&lt;int&gt;</code> won't compile.</p>`)],
  gen() { const t = R.int(0, 1);
    if (t === 0) { let a = [...Array(4)].map(() => R.int(1, 9)); const init = a.slice(), ops = []; for (let k = 0; k < 3; k++) { const o = R.pick(['add', 'addi', 'remi', 'set']); if (o === 'add') { const v = R.int(1, 9); a.push(v); ops.push(`list.add(${v});`); } if (o === 'addi') { const i = R.int(0, a.length), v = R.int(1, 9); a.splice(i, 0, v); ops.push(`list.add(${i}, ${v});`); } if (o === 'remi') { const i = R.int(0, a.length - 1); a.splice(i, 1); ops.push(`list.remove(${i});`); } if (o === 'set') { const i = R.int(0, a.length - 1), v = R.int(1, 9); a[i] = v; ops.push(`list.set(${i}, ${v});`); } }
      return textQ(`What does <code>list</code> contain at the end? (e.g. 1, 2, 3)${code(`ArrayList<Integer> list = new ArrayList<>(List.of(${init.join(', ')}));\n${ops.join('\n')}`)}`, a.join(', '), [`start [${init.join(', ')}]`, ...ops.map((o, i) => o), `→ <b>[${a.join(', ')}]</b>`], { check: v => norm(v) === norm(a.join(',')) }); }
    const q = R.pick([['get(i) on an ArrayList', 'O(1)'], ['get(i) on a LinkedList', 'O(n)'], ['add(0, x) on an ArrayList of n items', 'O(n)'], ['addFirst(x) on a LinkedList', 'O(1)'], ['containsKey on a HashMap (average)', 'O(1)'], ['put on a TreeMap', 'O(log n)'], ['contains(x) on an ArrayList', 'O(n)']]);
    return mcFrom(`What is the time complexity of <b>${q[0]}</b>?`, q[1], ['O(1)', 'O(log n)', 'O(n)', 'O(n log n)'], [q[1] === 'O(1)' ? 'direct index or hash bucket' : q[1] === 'O(n)' ? 'has to walk or shift up to n elements' : 'balanced tree height is log n', `→ <b>${q[1]}</b>`]); } });

/* ============================== CS 2340 · Computer Architecture ============================== */
const tc = (v, n) => (v < 0 ? v + 2 ** n : v).toString(2).padStart(n, '0');
CH.push({ id: 'numbers', course: '2340', ext: '.asm', title: 'Binary, hex & two\'s complement', blurb: 'Convert between bases, represent negatives, and spot overflow.',
  learn: [L('Bases', `<p>Each hex digit is exactly 4 bits: <code>0x3F = 0011 1111</code>. To convert decimal → binary, repeatedly divide by 2 and read the remainders bottom-up.</p><p>An n-bit <b>unsigned</b> value covers 0 … 2ⁿ − 1.</p>`, 'bits'),
    L('Two\'s complement', `<p>n bits cover −2ⁿ⁻¹ … 2ⁿ⁻¹ − 1. The top bit has weight <b>−2ⁿ⁻¹</b>. To negate: <b>invert all bits, then add 1</b>.</p><p><b>Sign extension:</b> copy the sign bit into the new high bits. <b>Overflow</b> happens when adding two numbers of the same sign gives the opposite sign.</p>`)],
  gen() { const t = R.int(0, 3);
    if (t === 0) { const v = R.int(20, 255); return textQ(`Convert <b>${v}</b> to 8-bit binary.`, v.toString(2).padStart(8, '0'), [`${v} = ${[...v.toString(2).padStart(8, '0')].map((b, i) => +b ? 2 ** (7 - i) : 0).filter(Boolean).join(' + ')}`, `→ <b>${v.toString(2).padStart(8, '0')}</b>`], { check: x => parseInt(x.replace(/^0b|\s/g, ''), 2) === v }); }
    if (t === 1) { const v = -R.int(1, 127); return textQ(`Write <b>${v}</b> in 8-bit two's complement.`, tc(v, 8), [`+${-v} = ${tc(-v, 8)}`, `invert → ${[...tc(-v, 8)].map(b => b === '0' ? 1 : 0).join('')}`, `add 1 → <b>${tc(v, 8)}</b>`], { check: x => x.replace(/^0b|\s/g, '') === tc(v, 8) }); }
    if (t === 2) { const v = R.int(256, 65535); return textQ(`Convert <b>0x${v.toString(16).toUpperCase()}</b> to decimal.`, String(v), [`${[...v.toString(16).toUpperCase()].map((d, i, a) => `${d}·16^${a.length - 1 - i}`).join(' + ')}`, `→ <b>${v}</b>`], { check: x => parseNum(x) === v }); }
    const a = R.int(-128, 127), b = R.int(-128, 127), s = a + b, ov = s > 127 || s < -128; return mcFrom(`In 8-bit two's complement, does <b>${a} + ${b}</b> overflow?`, ov ? `Yes: true result ${s} is outside −128…127` : `No: the result ${s} fits`, [`Yes: true result ${s} is outside −128…127`, `No: the result ${s} fits`, 'Yes: there is a carry out of the top bit', 'Only unsigned numbers can overflow'], ['8-bit two\'s complement range: −128 to 127', `${a} + ${b} = ${s}`, ov ? '→ <b>overflow</b> (the stored bits wrap to ' + ((s + 384) % 256 - 128) + ')' : '→ <b>no overflow</b>']); } });

const MREG = ['$t0', '$t1', '$t2', '$t3'];
CH.push({ id: 'mips', course: '2340', ext: '.asm', title: 'MIPS assembly', blurb: 'Trace registers through add, addi, sll, and, or, slt and branches. Decode instruction formats.',
  learn: [L('Core instructions', `${code('add  $t0, $t1, $t2   # t0 = t1 + t2\naddi $t0, $t1, 5     # t0 = t1 + 5   (immediate)\nsub  $t0, $t1, $t2   # t0 = t1 - t2\nsll  $t0, $t1, 2     # t0 = t1 << 2  (×4)\nsrl  $t0, $t1, 1     # logical shift right\nand / or / xor       # bitwise\nslt  $t0, $t1, $t2   # t0 = (t1 < t2) ? 1 : 0\nlw   $t0, 8($s0)     # t0 = Mem[s0 + 8]\nbeq  $t0, $t1, label # branch if equal')}<p>Destination comes <b>first</b>. Arrays of words step by 4 bytes, so <code>A[i]</code> is at <code>base + 4i</code>, often computed with <code>sll $t, $i, 2</code>.</p>`),
    L('Instruction formats', `<table class="t"><tr><th>type</th><th>fields (bits)</th><th>used by</th></tr><tr><td>R</td><td>op 6 | rs 5 | rt 5 | rd 5 | shamt 5 | funct 6</td><td>add, sub, and, or, slt, sll</td></tr><tr><td>I</td><td>op 6 | rs 5 | rt 5 | immediate 16</td><td>addi, lw, sw, beq, bne</td></tr><tr><td>J</td><td>op 6 | address 26</td><td>j, jal</td></tr></table><p>Branch target = PC + 4 + (offset × 4). The offset counts <b>instructions</b>, relative to the next one.</p>`, 'pipeline')],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const r = { '$t0': R.int(0, 12), '$t1': R.int(0, 12), '$t2': 0, '$t3': 0 }, init = { ...r }, prog = [], steps = [];
      for (let k = 0; k < 4; k++) { const op = R.pick(['add', 'addi', 'sub', 'sll', 'and', 'or', 'slt']), d = R.pick(MREG), a = R.pick(MREG), b = R.pick(MREG), im = R.int(1, 9), sh = R.int(1, 3);
        let v; if (op === 'add') v = r[a] + r[b]; if (op === 'addi') v = r[a] + im; if (op === 'sub') v = r[a] - r[b]; if (op === 'sll') v = r[a] << sh; if (op === 'and') v = r[a] & r[b]; if (op === 'or') v = r[a] | r[b]; if (op === 'slt') v = r[a] < r[b] ? 1 : 0;
        prog.push(op === 'addi' ? `addi ${d}, ${a}, ${im}` : op === 'sll' ? `sll  ${d}, ${a}, ${sh}` : `${op.padEnd(4)} ${d}, ${a}, ${b}`); steps.push(`${prog[k]} → ${d} = ${v}`); r[d] = v; }
      const ask = R.pick(MREG); return numQ(`Initially $t0 = ${init['$t0']}, $t1 = ${init['$t1']}, $t2 = 0, $t3 = 0. What is <b>${ask}</b> after this runs?${code(prog.join('\n'))}`, r[ask], '', [...steps, `→ ${ask} = <b>${r[ask]}</b>`], { tol: 0 }); }
    if (t === 1) { const ins = R.pick([['add $t0, $t1, $t2', 'R'], ['lw $t0, 4($s1)', 'I'], ['j loop', 'J'], ['beq $t0, $zero, done', 'I'], ['sll $t0, $t1, 2', 'R'], ['addi $sp, $sp, -8', 'I'], ['jal func', 'J'], ['slt $t2, $t0, $t1', 'R']]); return mcFrom(`What format is <code>${ins[0]}</code>?`, ins[1] + '-type', ['R-type', 'I-type', 'J-type'], ['R: three registers (or a shift amount). I: register(s) + 16-bit immediate/offset. J: 26-bit jump address.', `→ <b>${ins[1]}-type</b>`]); }
    const pc = 0x00400000 + 4 * R.int(0, 64), off = R.int(-8, 12), tgt = pc + 4 + off * 4; return textQ(`A <code>beq</code> at address <b>0x${pc.toString(16).toUpperCase().padStart(8, '0')}</b> has offset field <b>${off}</b>. What is the branch target address (hex)?`, '0x' + tgt.toString(16).toUpperCase().padStart(8, '0'), ['target = (PC + 4) + offset × 4', `= 0x${(pc + 4).toString(16).toUpperCase()} + ${off * 4}`, `→ <b>0x${tgt.toString(16).toUpperCase().padStart(8, '0')}</b>`], { check: x => parseInt(x.replace(/^0x/i, ''), 16) === tgt }); } });

CH.push({ id: 'performance', course: '2340', ext: '.asm', title: 'Performance & Amdahl\'s law', blurb: 'CPU time, CPI, MIPS and how much a speedup actually helps.',
  learn: [L('The performance equation', `<p class="mono">CPU time = Instruction count × CPI × Clock period = IC × CPI / Clock rate</p><p>Average CPI is a weighted average: Σ (fraction of instructions in class i × CPI of class i).</p><p>"A is n times faster than B" means time<sub>B</sub> / time<sub>A</sub> = n.</p>`),
    L('Amdahl\'s law', `<p>If a fraction <b>f</b> of execution time is sped up by a factor <b>s</b>:</p><p class="mono">Overall speedup = 1 / ((1 − f) + f / s)</p><p>Even with s → ∞, the speedup can never exceed 1/(1 − f). Make the common case fast.</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const ic = R.int(2, 9) * 1e9, cpi = R.real(1.1, 2.8, 1), ghz = R.pick([1.5, 2, 2.5, 3, 4]), T = ic * cpi / (ghz * 1e9); return numQ(`A program runs ${ic / 1e9}×10⁹ instructions with CPI ${cpi} on a ${ghz} GHz clock. CPU time in seconds?`, T, 's', [`time = IC × CPI / rate = ${ic / 1e9}×10⁹ × ${cpi} / ${ghz}×10⁹`, `= <b>${sig(T, 3)} s</b>`], { tol: .01 }); }
    if (t === 1) { const f = R.pick([.4, .5, .6, .75, .8, .9]), s = R.pick([2, 4, 5, 10, 20]), sp = 1 / ((1 - f) + f / s); return numQ(`${f * 100}% of a program's time is in code that you make ${s}× faster. Overall speedup?`, sp, '×', [`1 / ((1 − ${f}) + ${f}/${s})`, `= 1 / (${sig(1 - f, 3)} + ${sig(f / s, 3)}) = <b>${sig(sp, 3)}×</b>`, `(limit as s → ∞: ${sig(1 / (1 - f), 3)}×)`], { tol: .01 }); }
    const F = R.pick([[.5, .3, .2], [.4, .4, .2], [.6, .25, .15], [.45, .35, .2]]), C = [R.int(1, 2), R.int(2, 4), R.int(3, 6)], avg = F.reduce((s, f, i) => s + f * C[i], 0); return numQ(`Instruction mix: ALU ${Math.round(F[0] * 100)}% (CPI ${C[0]}), load/store ${Math.round(F[1] * 100)}% (CPI ${C[1]}), branch ${Math.round(F[2] * 100)}% (CPI ${C[2]}). Average CPI?`, Math.round(F[0] * 100) / 100 * C[0] + Math.round(F[1] * 100) / 100 * C[1] + Math.round(F[2] * 100) / 100 * C[2], '', ['weighted average of the CPIs', `${Math.round(F[0] * 100) / 100}·${C[0]} + ${Math.round(F[1] * 100) / 100}·${C[1]} + ${Math.round(F[2] * 100) / 100}·${C[2]}`, `= <b>${sig(Math.round(F[0] * 100) / 100 * C[0] + Math.round(F[1] * 100) / 100 * C[1] + Math.round(F[2] * 100) / 100 * C[2], 3)}</b>`], { tol: .01 }); void avg; } });

CH.push({ id: 'cache', course: '2340', ext: '.asm', title: 'Caches', blurb: 'Split an address into tag, index and offset, then predict hits and misses.',
  learn: [L('Address breakdown', `<p>For a direct-mapped cache with <b>B-byte blocks</b> and <b>N lines</b>, on 32-bit addresses:</p><ul><li>offset bits = log₂ B</li><li>index bits = log₂ N</li><li>tag bits = 32 − index − offset</li></ul><p>For a k-way set-associative cache, the index picks a <b>set</b>: index bits = log₂(N / k).</p><p class="note">Block address = ⌊address / B⌋. Line = block address mod N. Tag = ⌊block address / N⌋.</p>`),
    L('Average memory access time', `<p class="mono">AMAT = hit time + miss rate × miss penalty</p><p>Misses come in three kinds (the 3 Cs): <b>compulsory</b> (first touch), <b>capacity</b> (the cache is too small) and <b>conflict</b> (two blocks fight over one line).</p>`)],
  gen() { const t = R.int(0, 2);
    if (t === 0) { const B = R.pick([4, 8, 16, 32, 64]), Nlines = R.pick([16, 32, 64, 128, 256, 1024]), k = R.pick([1, 1, 2, 4]), off = Math.log2(B), idx = Math.log2(Nlines / k), tag = 32 - off - idx, ask = R.pick(['tag', 'index', 'offset']), v = { tag, index: idx, offset: off }[ask];
      return numQ(`A ${k === 1 ? 'direct-mapped' : k + '-way set-associative'} cache has ${Nlines} lines of ${B} bytes, with 32-bit addresses. How many <b>${ask}</b> bits?`, v, 'bits', [`offset = log₂ ${B} = ${off}`, `sets = ${Nlines}/${k} = ${Nlines / k} → index = ${idx}`, `tag = 32 − ${idx} − ${off} = ${tag}`, `→ <b>${v}</b>`], { tol: 0 }); }
    if (t === 1) { const N = 4, B = 4, addrs = [...Array(7)].map(() => 4 * R.int(0, 15)), lines = Array(N).fill(null); let hits = 0; const log = addrs.map(a => { const blk = Math.floor(a / B), l = blk % N, tg = Math.floor(blk / N), h = lines[l] === tg; if (h) hits++; else lines[l] = tg; return `${a}: block ${blk}, line ${l} → ${h ? 'hit' : 'miss'}`; });
      return numQ(`Direct-mapped cache: 4 lines, 4-byte blocks, initially empty. Byte addresses accessed: <b>${addrs.join(', ')}</b>. How many <b>hits</b>?`, hits, 'hits', [...log, `→ <b>${hits}</b>`], { tol: 0 }); }
    const ht = R.int(1, 2), mr = R.pick([.02, .05, .1, .2]), mp = R.pick([20, 50, 100, 200]); return numQ(`Hit time ${ht} cycle${ht > 1 ? 's' : ''}, miss rate ${mr * 100}%, miss penalty ${mp} cycles. AMAT?`, ht + mr * mp, 'cycles', [`AMAT = ${ht} + ${mr} × ${mp}`, `= <b>${sig(ht + mr * mp, 3)} cycles</b>`]); } });

CH.push({ id: 'floats', course: '2340', ext: '.asm', title: 'IEEE 754 floating point', blurb: 'Sign, biased exponent and mantissa: encode and decode single precision.',
  learn: [L('Single precision layout', `<p>32 bits: <b>1 sign | 8 exponent | 23 fraction</b>. Value = (−1)ˢ × 1.fraction × 2^(exponent − 127).</p><p>To encode: write the number in binary, normalize it to 1.xxx × 2ᵉ, store e + 127 as the exponent and the bits after the point as the fraction.</p>${code('-6.75 = -110.11₂ = -1.1011 × 2²\nsign = 1, exponent = 2 + 127 = 129 = 10000001\nfraction = 1011000...0\n→ 1 10000001 10110000000000000000000 = 0xC0D80000')}`, 'bits')],
  gen() { const t = R.int(0, 1); const v = R.pick([-1, 1]) * R.pick([0.5, 0.75, 1.25, 2.5, 3.75, 5.5, 6.75, 10.25, 12.5, 0.375, 20.5]);
    const dv = new DataView(new ArrayBuffer(4)); dv.setFloat32(0, v); const bits = dv.getUint32(0).toString(2).padStart(32, '0'), hex = '0x' + dv.getUint32(0).toString(16).toUpperCase().padStart(8, '0'), e = parseInt(bits.slice(1, 9), 2);
    if (t === 0) return numQ(`What is the stored (biased) exponent field, in decimal, for <b>${v}</b> in single precision?`, e, '', [`|${v}| = 1.${bits.slice(9).replace(/0+$/, '') || '0'}₂ × 2^${e - 127}`, `biased = ${e - 127} + 127 = <b>${e}</b>`], { tol: 0 });
    return textQ(`Encode <b>${v}</b> as a 32-bit IEEE 754 single (give hex, e.g. 0x40490000).`, hex, [`sign = ${bits[0]}`, `exponent = ${e - 127} + 127 = ${e} = ${bits.slice(1, 9)}`, `fraction = ${bits.slice(9)}`, `${bits[0]} ${bits.slice(1, 9)} ${bits.slice(9)} → <b>${hex}</b>`], { check: x => parseInt(x.replace(/^0x/i, ''), 16) === dv.getUint32(0) }); } });
